"""Versioned reviewer-response addendum; only complete experiments produce results."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def append_iteration3(blocks):
 path=ROOT/'results/iteration3/reviewer_analysis_summary.json'
 if not path.exists():return
 s=json.loads(path.read_text())
 def h(t):blocks.append({'kind':'heading','text':t})
 def p(t):blocks.append({'kind':'paragraph','text':t})
 def table(caption,heads,data):blocks.append({'kind':'table','caption':caption,'heads':heads,'data':data})
 def eq(tex,text):blocks.append({'kind':'equation','tex':tex,'text':text})
 blocks.append({'kind':'page'});h('Appendix C. Reviewer-driven label, geometry and recalibration experiments')
 p('This expansion was designed after the original real-interface outcomes were inspected. It adds explicit diagnosis of the base grounder, the gate and annotation sensitivity. All original policy definitions and final labels remain frozen. New split-based estimates are exploratory; a retrospective split does not create a previously untouched confirmatory test.')
 h('C.1 Label and geometry sensitivity')
 table('Frozen accepts evaluated under alternative human references. Consensus-only changes the evaluation population and is not directly comparable in magnitude.', ['Labels','Policy','N','Accept','Errors','Risk'],[[r['labels'],r['policy'],r['n'],r['accepted'],r['incorrect_accepted'],f"{100*r['selective_risk']:.1f}%" if r['selective_risk'] is not None else 'undefined'] for r in s['sensitivity'] if r['criterion']=='strict' and r['policy'] in ['B','D','E']])
 p('A-only and B-only boxes are mapped through the same recorded image scale and padding as the final labels. Consensus-only includes the original two-annotator consensus subset, excluding reviewer-resolved flags. This is an observed sensitivity analysis, not a model-based bound on unknown true risk. The label-dependent error differences show why the pending independent audit matters.')
 table('Final human labels, real751: localization criterion sensitivity. IoU0.3 uses overlap alone; strict uses center-in-box and IoU0.5.', ['Criterion','Policy','Correct boxes /131 unique','Accept','Errors','Risk'],[[r['criterion'],r['policy'],r['correct_localizations'],r['accepted'],r['incorrect_accepted'],f"{100*r['selective_risk']:.1f}%" if r['selective_risk'] is not None else 'undefined'] for r in s['sensitivity'] if r['labels']=='final' and r['policy'] in ['B','D','E']])
 hu=s['human_reference']
 p(f"On {hu['n']} real cases that both annotators label unique, mean human-to-human IoU is {hu['mean_iou']:.3f}. Box agreement reaches IoU0.3 in {100*hu['iou_pass_rate']['0.3']:.1f}%, IoU0.5 in {100*hu['iou_pass_rate']['0.5']:.1f}%, and IoU0.75 in {100*hu['iou_pass_rate']['0.75']:.1f}%. A's box center lies in B's box in {100*hu['A_center_in_B']:.1f}%; the reverse direction is {100*hu['B_center_in_A']:.1f}%. These conditional agreement rates are an annotation reference, not an absolute human or model ceiling; they exclude status disagreements and use no independently verified true boxes.")
 h('C.2 Brier skill and threshold-free ranking')
 eq(r'\mathrm{BSS}=1-\frac{\frac{1}{n}\sum_i(s_i-y_i)^2}{\frac{1}{n}\sum_i(c-y_i)^2}.','Brier skill = 1 - model Brier loss / constant-reference Brier loss.')
 p('Brier skill is 1 minus the model Brier score divided by a constant-reference Brier score. The retrospective reference predicts the evaluated positive prevalence and is an optimistic in-sample reference. The deployment-oriented reference uses prevalence estimated only from valid real calibration outputs. The all-real E_real_fit row mixes fitting and non-fitting cases and is diagnostic; its test-only row is the relevant recovery estimate.')
 table('Brier loss and skill under the strict correctness event. Higher skill is better; negative skill is worse than the constant.', ['Scope','Score','Brier','Retrospective constant','Skill','Calibration-constant skill'],[[{'all_valid_real':'All valid real','exploratory_test_valid':'Test valid'}[r['scope']],r['policy'],f"{r['brier']:.4f}",f"{r['retrospective_constant_brier']:.4f}",f"{r['retrospective_brier_skill']:.3f}",f"{r['calibration_constant_skill']:.3f}"] for r in s['skill']])
 p('Low ECE alone is insufficient when correct localizations are rare. On all 740 valid real outputs, the constant prevalence is 41/740, whose Brier loss is 0.05234; original E has 0.06125 and skill -0.170. On the exploratory held-out valid subset, real-fitted logistic E improves Brier loss to 0.05822 versus 0.07345 for the original E and 0.06616 for the calibration-prevalence constant, a 12.0% Brier skill relative to that constant. Probability estimation improves without demonstrating recovery of a 10%-risk automation policy.')
 table('Threshold-free metrics on 740 valid real outputs. 1,000 source-cluster resamples give 95% intervals. AUROC higher and AURC lower are better.', ['Score','AUROC [95% CI]','AURC [95% CI]'],[[r['policy'],f"{r['auroc']:.3f} [{r['cluster_ci']['auroc']['low']:.3f}, {r['cluster_ci']['auroc']['high']:.3f}]",f"{r['aurc']:.3f} [{r['cluster_ci']['aurc']['low']:.3f}, {r['cluster_ci']['aurc']['high']:.3f}]"] for r in s['ranking'] if r['scope']=='valid_outputs'])
 p('AURC integrates right-continuous threshold risk over observed coverage. Equal confidence scores enter together, preventing arbitrary within-tie ordering. Separate machine-readable results include all cases with parser failures placed below valid scores, and the unique-target valid subset. B and E have almost identical AUROC; their overlapping ranking intervals and similar AURC give no evidence that the extra native signals add strong discrimination on this real cohort. AUROC and AURC diagnose ranking, not calibrated risk or downstream harm.')
 h('C.3 Exploratory real-data recovery with source separation')
 eq(r'p_j=\sum_{e=0}^{E_j}\binom{K_j}{e}\alpha^e(1-\alpha)^{K_j-e},\quad p_j\leq\delta/M.','LTT tests each fixed accepted-error risk null with the exact binomial lower-tail probability; M is the number of score-threshold tests.')
 split=s['design']['split'];p('Source images are assigned deterministically to fit/calibration/test partitions by a seeded hash; no screenshot crosses partitions. The split contains '+', '.join(f"{k}: {v['cases']} cases/{v['clusters']} source clusters" for k,v in split.items())+'. E_real_fit is a new L2 logistic diagnostic fitted on valid fit-partition outputs only; it does not replace the frozen original E.')
 p('For Learn then Test [11], the threshold grid is fixed at 0,0.05,...,1. We test the null that conditional accepted-error risk is at least 10% using a one-sided exact binomial lower-tail p-value. Bonferroni correction covers all 21 thresholds and six scores at overall delta 0.05. To address within-screenshot dependence, one case is independently hash-selected from every source cluster, using no labels. Certified thresholds maximize calibration acceptance within the passing family; if none passes, the procedure abstains. Binomial guarantees target this sampled-cluster distribution and require independent, identically distributed source clusters and a fixed calibration protocol. Those assumptions cannot be fully established retrospectively here, so certification is a diagnostic property of the stated procedure rather than a deployment guarantee.')
 p('The empirical comparator maximizes calibration acceptance subject to observed risk at most 10%, without a statistical guarantee. Neither this comparator nor LTT finds a qualifying threshold for any of the six scores under the strict criterion. Thus the implemented recovery experiment does not show useful automation at the specified 10% risk target. An alternative risk budget or criterion would require an explicitly separate analysis; it is not selected from test outcomes.')
 table('Exploratory recovery on 229 test cases. Zero accepts means undefined selective risk, not zero risk.', ['Score','Empirical accepts','LTT accepts','Incorrect accepts'],[[n,next(r['accepted'] for r in s['recovery'] if r['policy']==n and r['method'].startswith('empirical')),next(r['accepted'] for r in s['recovery'] if r['policy']==n and r['method'].startswith('LTT') and r['test_scope']=='all test cases descriptive'),0] for n in ['B','C','D','E','uniqueness','E_real_fit']])
 p('The source-selected test unit has 220 cases; full 229-case test metrics are also retained descriptively. Recalibration can improve probabilities and alter rejection thresholds, but it cannot create correct boxes that the grounder did not produce. At most 41/131 real unique cases satisfy the strict localization rule in the original pass. This separates weak base localization from a claim that rejection itself is wrong.')
 h('C.4 New collection protocol and completion status')
 collection_path=ROOT/'results/iteration3/collection_summary.json';collection=json.loads(collection_path.read_text()) if collection_path.exists() else {}
 completed=collection.get('repeat_progress',{});done=sum(x['complete'] for x in completed.values())
 p(f"The new Jev protocol fixes four additional original-prompt passes on 751 real cases, yielding five passes including the existing one, plus two prewritten prompt variants. It therefore plans 4,506 additional requests. New requests use separate repeat/prompt IDs and immutable protocol hashes; non-auth attempted IDs, including timeouts and malformed outputs, are not silently resent. At manuscript generation, {done}/7 complete pass/variant cohorts are available, including the existing original pass. Partial collections are not used for headline metrics.")
 if collection.get('repeat_consistency'):
  r=collection['repeat_consistency'];p(f"Across five complete original-prompt passes, correctness changes in {r['correctness_changes']}/{r['cases']} cases. Mean per-case modal match-count-label fraction is {r['mean_match_label_agreement']:.3f}. Between-pass policy metrics and per-case consistency are retained separately; repeated observations are not pooled as independent screenshots.")
  ops=collection['raw_usage'];p(f"The completed additional collection has {ops['network_attempts']:,} attempts, {sum(v['failures'] for k,v in completed.items() if k!='original:r1')} fail-closed outputs, {ops['input_tokens']:,} input tokens and {ops['output_tokens']:,} output tokens. Including recorded usage from malformed responses, the additional rate-based cost estimate is ${ops['estimated_cost_usd']:.6f}; output tokens are free at the recorded provider rate. No failed attempt was automatically repeated.")
  p('Across the five original-prompt passes, B accepts 43-47 cases and D 21-26; D conditional error risk ranges 57.1-71.4%. E accepts 0-1 case. The literal prompt yields 24 D accepts/15 errors, and the conservative prompt yields 32/23. Prompt changes do not recover useful low-risk coverage under these frozen thresholds. These are descriptive within-case repetitions, not additional independent test screens.')
  if collection.get('decision_repeatability'):
   dr=collection['decision_repeatability'];p('The frozen accept decision changes across original-prompt passes for '+', '.join(f"{name}: {count}/751 cases" for name,count in dr['policy_acceptance_flip_cases'].items())+f". Mean pairwise box IoU across {dr['valid_box_pair_count']:,} valid within-case output pairs is {dr['mean_valid_pair_box_iou']:.3f}; pairs involving malformed outputs are excluded from this geometry diagnostic.")
  m=collection['completed_metrics'];table('Completed Jev pass metrics (751 cases each). Errors are incorrect accepts; malformed responses remain in coverage denominators.', ['Pass','Policy','Accept','Errors','Risk'],[[r['cohort'],r['policy'],r['accepted'],r['incorrect_accepted'],f"{100*r['selective_risk']:.1f}%" if r['selective_risk'] is not None else 'undefined'] for r in m if r['policy'] in ['B','D','E']])
 base=collection.get('baseline',{});p('A same-input local baseline pins Qwen2.5-VL-7B [13] through Ollama with model digest recorded, Q4_K_M quantization, deterministic decoding, seed 1729, context 4096 and maximum 180 output tokens. The prompt and JSON schema are frozen before the first response. It requests a forced box plus verbalized presence/uniqueness/box-confidence scores. These scores are prompted self-reports rather than native Jev probabilities. Inference is serial on an 18GiB Apple-arm64 Mac. The local compute/energy price is unmeasured, so API charge and total economic cost are not equated.')
 if base.get('state')=='COMPLETE':
  table('Completed same-data comparison on 751 real cases. Both models use the same prepared images; strict correctness includes eligibility, center and IoU.', ['Model','Valid','Strict /131 unique','IoU0.3 /131','Center /131','One-label accepts/errors'],[[n,r['valid_outputs'],r['strict_correct'],r['iou03_correct'],r['center_correct'],f"{r['one_label_gate']['accepted']}/{r['one_label_gate']['errors']}"] for n,r in base['primary_metrics'].items()])
  ls=base.get('label_sensitivity',[])
  if ls:
   table('Same-input strict localization under alternative human references. Consensus-only is a smaller selected population, not a noise bound.', ['Reference','Cases','Unique targets','Jev correct / unique','Qwen correct / unique'],[[label,next(r['n'] for r in ls if r['labels']==label),next(r['unique_n'] for r in ls if r['labels']==label)]+[f"{next(r['correct'] for r in ls if r['labels']==label and r['model']==name and r['criterion']=='strict')}/{next(r['unique_n'] for r in ls if r['labels']==label)}" for name in ['Jev','Qwen']] for label in ['final','A_only','B_only','consensus_only']])
   p('The observed strict-accuracy ordering persists under each reference, while absolute performance and even the number of unique targets vary substantially with annotation choice. This sensitivity is evidence for continued label audit, not proof that any reference is correct. Center-only and IoU0.3 variants are retained in the machine-readable sensitivity table.')
  p(f"Local Qwen request-to-full-response latency is {base['latency_mean_ms']/1000:.2f}s mean and {base['latency_p95_ms']/1000:.2f}s p95, including the cold first call. This measures the local quantized deployment, not a hosted-Qwen service or a hardware-normalized speed comparison.")
  p('All 951 input-image hashes match between Jev and Qwen, and the pinned Qwen model/protocol hashes are unchanged across the resumed collection. The 62 baseline failures all violate box geometry. The completed per-case comparison ledger and paired bootstrap intervals are included in the artifact. Collection was resumed after 446 attempts without repeating earlier logged inputs.')
 else:p(f"The Qwen collection is {base.get('state','NOT_STARTED')}: {base.get('attempted',0)}/951 attempted inputs. No complete same-data accuracy or latency comparison is claimed from this partial run. The published contextual table remains historical background, pending completion of this stronger baseline.")
 fresh=ROOT/'fresh_real_review/status.json'
 if fresh.exists():
  v=json.loads(fresh.read_text());p(f"A new source-disjoint candidate pool contains {v['tasks']} tasks on {v['source_images']} ScreenSpot-Pro screenshots [14]. It has 60 source-positive instructions, 60 cross-application absent candidates and 60 generic multiple-target candidates. File-name and decoded-pixel duplicates against the prior 951 cases are rejected. These are candidate construction categories, not labels; two blind human passes and independent adjudication must establish the final states before confirmatory inference. The professional desktop source is a new domain, not a balanced mobile/web/desktop sample. No model predictions are collected on these candidates before labeling.")
 p('The independent 100-case audit (60 flagged, 40 consensus) also remains a human task. Automated analysis and an annotation package cannot substitute for completed human responses. Future labels must create a versioned sensitivity cohort rather than overwrite the frozen experiment.')
